class Document {
  private content: string;
  constructor(text: string) { this.content = text; }
  setContent(text: string) { this.content = text; }
  createSnapshot() { return new DocumentSnapshot(this.content); }
  restore(snapshot: DocumentSnapshot) { this.content = snapshot.getContent(); }
}
class DocumentSnapshot {
  constructor(private state: string) {}
  getContent() { return this.state; }
}
class DocumentHistory { private snapshots: DocumentSnapshot[] = []; push(s: DocumentSnapshot) { this.snapshots.push(s); } pop() { return this.snapshots.pop(); } }

class Editor {
  private state: any;
  createSnapshot() { return JSON.stringify(this.state); }
  restore(snapshot: string) { this.state = JSON.parse(snapshot); }
}
class EditorHistory {
  private snapshots: string[] = [];
  push(s: string) { this.snapshots.push(s); }
  get(idx: number) { return this.snapshots[idx]; }
}
// No pruning, history grows indefinitely

class Widget {
  private state: any;
  // Version A
  createSnapshot() { return new WidgetSnapshot(this.state); }
  restore(snapshot: WidgetSnapshot) { this.state = snapshot.getState(); }
}
class WidgetSnapshot { constructor(private state: any) {} getState() { return this.state; } }

// Version B
class WidgetV2 {
  private state: any;
  saveState(history: any[]) { history.push(this.state); }
  restoreState(history: any[]) { this.state = history.pop(); }
}
